from textual.app import ComposeResult, App
from textual.containers import Horizontal
from textual.widgets import DirectoryTree, Static
from pathlib import Path


class TextDisplay(Static):
    DEFAULT_CSS = """
    TextDisplay {
        width: 1fr;
        height: 100%;
        border: solid $accent;
        overflow: auto;
    }
    """

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.text_content = ""

    def render(self) -> str:
        return self.text_content

    def set_text(self, text: str) -> None:
        self.text_content = text
        self.update()


class DirectoryTextApp(App):
    CSS = """
    Screen {
        layout: vertical;
    }

    Horizontal {
        height: 100%;
        width: 100%;
    }

    DirectoryTree {
        width: 50%;
        height: 100%;
        border: solid $accent;
    }

    TextDisplay {
        width: 50%;
        height: 100%;
    }
    """

    def compose(self) -> ComposeResult:
        with Horizontal():
            yield DirectoryTree(str(Path.home()))
            yield TextDisplay()

    def on_mount(self) -> None:
        self.title = "Directory Tree & Text Viewer"

    def on_directory_tree_file_selected(self, event: DirectoryTree.FileSelected) -> None:
        text_display = self.query_one(TextDisplay)
        try:
            with open(event.file_path, "r", encoding="utf-8") as f:
                text_display.set_text(f.read())
        except Exception as e:
            text_display.set_text(f"Error reading file: {type(e).__name__}: {e}")


if __name__ == "__main__":
    app = DirectoryTextApp()
    app.run()

